diff --git a/scripts/test-migration.mjs b/scripts/test-migration.mjs
new file mode 100644
index 0000000..683c7c2
--- /dev/null
+++ b/scripts/test-migration.mjs
@@ -0,0 +1,14 @@
+import { readFileSync } from 'node:fs';
+const src = readFileSync('gemini.ts', 'utf8');
+const html = readFileSync('index.html', 'utf8');
+const fail = (m) => { console.error('FAIL: ' + m); process.exit(1); };
+const fn = /export function supportsSamplingParams[\s\S]*?\n}\n/.exec(src);
+if (!fn) fail('supportsSamplingParams missing');
+const f = new Function(fn[0].replace('export ', '').replace(/: string\): boolean/, ')').replace('(model)', '(model)') + '; return supportsSamplingParams;')();
+const cases = { 'gemini-2.5-pro': true, 'gemini-3.5-flash-lite': true, 'gemini-3.6-flash': false, 'gemini-3.8-flash': false, 'gemini-3.10-pro': false, 'custom': true };
+for (const [k, v] of Object.entries(cases)) if (f(k) !== v) fail(k);
+if (src.includes('gemini-embedding-2-preview\'')) fail('old embedding id');
+if (!src.includes("model: 'gemini-embedding-2'")) fail('new embedding id');
+if (html.includes('gemini-3-pro-preview')) fail('retired model in UI');
+if (/temperature: 0\.9,/.test(src)) fail('unconditional temperature');
+console.log('ok');
